create table if not exists public.kana_db (
  id bigint generated always as identity primary key,
  character text not null,
  kana_type text not null check (kana_type in ('hiragana', 'katakana')),
  romaji text not null,
  group_name text not null,
  sort_order int not null
);

alter table public.kana_db enable row level security;

drop policy if exists "public read" on public.kana_db;
create policy "public read"
  on public.kana_db
  for select
  to anon, authenticated
  using (true);

-- Idempotent: safe to re-run without creating duplicate rows.
delete from public.kana_db;

